// === kalkulator.js ===
let riwayat = [];
function catat(op, hasil) {
  riwayat.push(`${op} = ${hasil}`);
  return hasil;
}
export function tambah(a, b) {
  return catat(`${a} + ${b}`, a + b);
}
export function lihatRiwayat() {
  return riwayat.join("; ");
}
// === main.js ===
import * as K from "./kalkulator.js";
K.tambah(2, 3);
K.tambah(10, 5);
console.log(K.lihatRiwayat());
console.log(typeof K.catat, typeof K.riwayat);

