// === diskon.js ===
export function persenDiskon(qty) {
  return qty >= 10 ? 20 : qty >= 5 ? 10 : 0;
}
export function hargaAkhir(harga, qty) {
  const total = harga * qty;
  return total - (total * persenDiskon(qty)) / 100;
}
// === main.js ===
import * as Diskon from "./diskon.js";
console.log(Diskon.hargaAkhir(10000, 5));
console.log(Diskon.hargaAkhir(10000, 10));
console.log(Object.keys(Diskon).join(", "));

